const rows = $('Lay Gia 1h').all().map(i => i.json).map(r => ({
  ...r,
  close: parseFloat(r.close),
  high: parseFloat(r.high),
  low: parseFloat(r.low),
  open_time: new Date(r.open_time)
}))
// LOC RAC NGAY TU GOC: bo cac dong co high/low/close khong hop le (null, NaN, 0, high < low)
.filter(r =>
  Number.isFinite(r.close) && Number.isFinite(r.high) && Number.isFinite(r.low) &&
  r.high > 0 && r.low > 0 && r.close > 0 && r.high >= r.low
)
.sort((a, b) => a.open_time - b.open_time);

const quantRows = $('Lay Quant Metrics').all().map(i => i.json);
const maxDDBySymbol = {};
for (const q of quantRows) maxDDBySymbol[q.symbol] = parseFloat(q.max_drawdown_pct);

const bySymbol = {};
for (const r of rows) {
  if (!bySymbol[r.symbol]) bySymbol[r.symbol] = [];
  bySymbol[r.symbol].push(r);
}

function pctReturns(candles) {
  const rets = [];
  for (let i = 1; i < candles.length; i++) {
    const prev = candles[i - 1].close;
    const cur = candles[i].close;
    if (prev > 0) rets.push(((cur - prev) / prev) * 100);
  }
  return rets;
}

function stdev(arr) {
  if (arr.length === 0) return 0;
  const m = arr.reduce((a, b) => a + b, 0) / arr.length;
  return Math.sqrt(arr.reduce((a, b) => a + (b - m) ** 2, 0) / arr.length);
}

function pearson(x, y) {
  const n = Math.min(x.length, y.length);
  if (n < 2) return null;
  const xs = x.slice(-n), ys = y.slice(-n);
  const mx = xs.reduce((a, b) => a + b, 0) / n;
  const my = ys.reduce((a, b) => a + b, 0) / n;
  let cov = 0, sx = 0, sy = 0;
  for (let i = 0; i < n; i++) {
    cov += (xs[i] - mx) * (ys[i] - my);
    sx += (xs[i] - mx) ** 2;
    sy += (ys[i] - my) ** 2;
  }
  if (sx === 0 || sy === 0) return null;
  return cov / Math.sqrt(sx * sy);
}

function atr(candles, period) {
  const trs = [];
  for (let i = 0; i < candles.length; i++) {
    if (i === 0) { trs.push(candles[i].high - candles[i].low); continue; }
    const pc = candles[i - 1].close;
    trs.push(Math.max(candles[i].high - candles[i].low, Math.abs(candles[i].high - pc), Math.abs(candles[i].low - pc)));
  }
  const validTrs = trs.filter(t => Number.isFinite(t) && t >= 0);
  if (validTrs.length < period) return { current: null, average: null };
  const recent = validTrs.slice(-period);
  const currentATR = recent.reduce((a, b) => a + b, 0) / period;
  const avgATR = validTrs.reduce((a, b) => a + b, 0) / validTrs.length;
  return { current: currentATR, average: avgATR };
}

const btcCandles = bySymbol['BTCUSDT'] || [];
const btcReturns = pctReturns(btcCandles);

const results = [];

for (const symbol in bySymbol) {
  const candles = bySymbol[symbol];
  if (candles.length < 30) continue;

  const returns = pctReturns(candles);
  const vol = stdev(returns);

  const atrInfo = atr(candles, 14);
  let atrRatio = null, atrRegime = 'khong_du_du_lieu';
  if (atrInfo.current !== null && atrInfo.average > 0) {
    atrRatio = atrInfo.current / atrInfo.average;
    if (atrRatio > 1.5) atrRegime = 'tang_cao';
    else if (atrRatio < 0.7) atrRegime = 'thap';
    else atrRegime = 'binh_thuong';
  }

  const corr = symbol === 'BTCUSDT' ? 1 : pearson(returns, btcReturns);
  const maxDD = maxDDBySymbol[symbol] !== undefined ? maxDDBySymbol[symbol] : null;

  // Xep hang rui ro dua tren 3 yeu to: volatility, atr regime, max drawdown
  let highCount = 0;
  const reasons = [];

  if (vol > 3) { highCount++; reasons.push(`bien dong cao (${vol.toFixed(2)}%/gio)`); }
  else if (vol > 1) { reasons.push(`bien dong trung binh (${vol.toFixed(2)}%/gio)`); }
  else { reasons.push(`bien dong thap (${vol.toFixed(2)}%/gio)`); }

  if (atrRegime === 'tang_cao') { highCount++; reasons.push(`ATR dang tang cao bat thuong (x${atrRatio.toFixed(2)} so voi trung binh)`); }
  else if (atrRegime === 'thap') { reasons.push('ATR dang thap hon binh thuong'); }

  if (maxDD !== null) {
    if (maxDD > 30) { highCount++; reasons.push(`max drawdown lich su cao (${maxDD.toFixed(1)}%)`); }
    else if (maxDD > 15) { reasons.push(`max drawdown lich su trung binh (${maxDD.toFixed(1)}%)`); }
    else { reasons.push(`max drawdown lich su thap (${maxDD.toFixed(1)}%)`); }
  }

  let riskLevel = 'LOW';
  if (highCount >= 2) riskLevel = 'HIGH';
  else if (highCount === 1) riskLevel = 'MEDIUM';

  const riskScore = Math.min(100, Math.round((vol / 5 * 40) + (atrRatio ? Math.min(atrRatio, 3) / 3 * 30 : 15) + (maxDD ? Math.min(maxDD, 50) / 50 * 30 : 15)));

  if (corr !== null) {
    reasons.push(`tuong quan voi BTC: ${corr.toFixed(2)}`);
  }

  results.push({
    symbol,
    volatility_pct: Math.round(vol * 100) / 100,
    atr_regime: atrRegime,
    atr_regime_ratio: atrRatio !== null ? Math.round(atrRatio * 100) / 100 : null,
    correlation_btc: corr !== null ? Math.round(corr * 100) / 100 : null,
    max_drawdown_pct: maxDD,
    risk_level: riskLevel,
    risk_score: riskScore,
    reason: reasons.join('; ')
  });
}

return results.map(r => ({ json: r }));
